<script setup lang="ts">import type {Dataset} from '../types/domain';defineProps<{modelValue:number;datasets:Dataset[]}>();defineEmits(['update:modelValue']);</script><template><label>楼宇数据集<select :value="modelValue" @change="$emit('update:modelValue',Number(($event.target as HTMLSelectElement).value))"><option v-for="d in datasets" :key="d.id" :value="d.id">{{d.name}} / {{d.building_count}}栋</option></select></label></template>
